changeSet.sql:
INSERT INTO note_sentence (note_id, sentence_id, position, origin_sentence_id, origin_migration_id, origin_commit_hash, sentence_id_history, migration_confidence, created_at, created_by) SELECT n.note_id, n.sentence_id, n.position, v1.origin_sentence_id, v1.origin_migration_id, v1.origin_commit_hash, COALESCE(vl.sentence_id_history, '[]'::jsonb), vl.migration_confidence, n.created_at, n.user_id FROM note n LEFT JOIN LATERAL ( SELECT origin_sentence_id, origin_migration_id, origin_commit_hash FROM note_version v WHERE v.note_id = n.note_id ORDER BY v.version ASC LIMIT 1 ) v1 ON true LEFT JOIN LATERAL ( SELECT sentence_id_history, migration_confidence FROM note_version v WHERE v.note_id = n.note_id ORDER BY v.version DESC LIMIT 1 ) vl ON true WHERE n.sentence_id IS NOT NULL ON CONFLICT (note_id, sentence_id) DO NOTHING;
INSERT INTO note_scratchpad (note_id, scratchpad_id, created_at, removed_at) SELECT n.note_id, n.scratchpad_id, n.created_at, CASE WHEN EXISTS ( SELECT 1 FROM scratchpad sp, jsonb_path_query(sp.doc, 'strict $.**.content[*] ? (@.type == "noteRef")') r WHERE sp.scratchpad_id = n.scratchpad_id AND sp.deleted_at IS NULL AND (r->'attrs'->>'noteId') ~ '^[0-9]+$' AND (r->'attrs'->>'noteId')::int = n.note_id) THEN NULL ELSE n.updated_at END FROM note n WHERE n.scratchpad_id IS NOT NULL ON CONFLICT (note_id, scratchpad_id) DO NOTHING;
INSERT INTO note_scratchpad (note_id, scratchpad_id, created_at) SELECT DISTINCT n.note_id, sp.scratchpad_id, sp.updated_at FROM scratchpad sp, jsonb_path_query(sp.doc, 'strict $.**.content[*] ? (@.type == "noteRef")') r JOIN note n ON (r->'attrs'->>'noteId') ~ '^[0-9]+$' AND n.note_id = (r->'attrs'->>'noteId')::int WHERE sp.deleted_at IS NULL ON CONFLICT (note_id, scratchpad_id) DO UPDATE SET removed_at = NULL;
